\label{lemma:spectral}
Let $\pi \colon \tX \to X$ be a proper morphism with fibers of dimension at most~$1$.
Let $\cF$ be a possibly unbounded complex of quasicoherent sheaves on $\tX$ and let $\cH^i(\cF)$ be its cohomology sheaf in degree $i$.
The spectral sequence $R^i\pi_*(\cH^j(\cF)) \Rightarrow \cH^{i+j}(\pi_*(\cF))$ degenerates at the second page, 
and gives for each $i$ an exact sequence
\begin{equation*}
0 \to R^1\pi_*\cH^{i-1}(\cF) \to \cH^i(\pi_*(\cF)) \to R^0\pi_*\cH^i(\cF) \to 0.
\end{equation*}
In particular, if $\cH^i(\pi_*(\cF)) = 0$ for $i \le p$ for some integer $p$, then $\pi_*(\cH^i(\cF)) = 0$ for $i \le p - 1$ and
\begin{equation*}
\pi_*\cF \cong \pi_*(\tau^{\ge p}\cF),
\end{equation*}
where $\tau$ stands for the truncation functor with respect to the canonical filtration.

\label{proposition:serre-gorenstein}
Let $X$ be a projective Gorenstein $\kk$-scheme of dimension $n$.
If either $\cF$ or $\cG$ is a perfect complex, there is a natural Serre duality isomorphism
\begin{equation*}
\Ext^i(\cF,\cG)^\vee \cong \Ext^{n-i}(\cG,\cF \otimes \omega_X).
\end{equation*}

\label{proposition:tx-excol}
Let $X$ be a sextic du Val del Pezzo surface over an algebraically closed field $\kk$ 
and let~$\pi \colon \tX \to X$ be its minimal resolution of singularities. 
There is a semiorthogonal decomposition
\begin{equation}
\label{eq:dbtx}
\bD(\tX) = \langle \tcA_1, \tcA_2, \tcA_3  \rangle,
\end{equation}
whose components are generated by the following exceptional collections of line bundles
\begin{equation}
\begin{aligned}
\label{eq:tx-excol}
\tcA_1 &= \langle \cO_\tX \rangle,\\
\tcA_2 &= \langle \cO_\tX(h - e_1), \cO_\tX(h - e_2), \cO_\tX(h - e_3) \rangle,\\
\tcA_3 &= \langle \cO_\tX(h), \cO_\tX(2h - e_1 - e_2 - e_3) \rangle. 
\end{aligned}
\end{equation}

\label{lemma:dual-sod-tx}
The semiorthogonal decomposition~\eqref{eq:dbtx-dual} is right mutation-dual to~\eqref{eq:dbtx}, i.e., 
\begin{equation*}
\tcA_1^\vee = \tcA_1,
\qquad
\tcA_2^\vee = \LL_{\tcA_1}(\tcA_2),
\quad\text{and}\quad 
\tcA_3^\vee = \LL_{\tcA_1}(\LL_{\tcA_2}(\tcA_3)) = \tcA_3 \otimes \omega_\tX.
\end{equation*}

The claim is trivial for the first component, since $\tcA_1^\vee  = \langle \cO_\tX^\vee  \rangle = \langle \cO_\tX \rangle = \tcA_1$,
and is easy for the last component, since $\LL_{\tcA_1}(\LL_{\tcA_2}(\tcA_3)) = \tcA_3  \otimes \omega_\tX$ and
\begin{equation}\label{eq:ce3-dual}
\begin{aligned}
& \cO_\tX(h) \otimes \omega_\tX && \cong \cO_\tX(-2h + e_1 + e_2 + e_3) && \cong \cO_\tX(2h - e_1 - e_2 - e_3)^\vee,\\
& \cO_\tX(2h - e_1 - e_2 - e_3) \otimes \omega_\tX && \cong \cO_\tX(-h) && \cong \cO_\tX(h)^\vee.
\end{aligned}
\end{equation} 
Finally, for the second component we have 
$\LL_{\tcA_1}(\tcA_2) = \tcA_1^\perp \cap \tcA_3^\perp = (\tcA_1^\vee)^\perp \cap  {}^\perp(\tcA_3 \otimes \omega_X) = \tcA_2^\vee$
by Serre duality.

The component $\tcA_1$ is generated by a single exceptional object, hence is equivalent to $\bD(\kk)$.
So, in view of Proposition~\ref{proposition:rm-equivalence} to prove the proposition it is enough to compute $\Ext$-spaces 
between the exceptional line bundles forming the components $\tcA_2$ and $\tcA_3$ of the semiorthogonal decomposition~\eqref{eq:dbtx}.

First of all, we have
\begin{equation*}
\Ext^p(\cO_\tX(h-e_i), \cO_\tX(h-e_j)) \cong H^p(\tX, \cO_\tX(e_i - e_j)).
\end{equation*}
Assuming $i \ne j$ and using exact sequences (note that $e_i\cdot e_j = 0$ and $e_i^2 = -1$ by Lemma~\ref{lemma:pic-tx})
\begin{equation*}
0 \to \cO_\tX(e_i - e_j) \to \cO_\tX(e_i) \to \cO_{E_j} \to 0,
\qquad\qquad
0 \to \cO_\tX \to \cO_\tX(e_i) \to \cO_{E_i}(-1) \to 0,
\end{equation*}
we obtain an exact sequence
\begin{equation*}
0 \to H^0(\tX, \cO_\tX(e_i - e_j)) \to \kk \to \kk \to H^1(\tX, \cO_\tX(e_i - e_j)) \to 0,
\end{equation*}
where the middle map is given by the restriction to $E_j$ of the equation of $E_i$.
This restriction vanishes if and only if $E_j$ is a component of $E_i$ --- in this case we deduce that $\Ext^\bullet(\cO_\tX(h-e_i), \cO_\tX(h-e_j)) \cong \kk \oplus \kk[-1]$,
and otherwise $\Ext^\bullet(\cO_\tX(h-e_i), \cO_\tX(h-e_j)) = 0$.
By Proposition~\ref{proposition:rm-equivalence} this gives the required description of $\tcA_2$ in types from~0 to 3.
In the last two types (4 and 5) it remains to check that multiplication map
\begin{equation}\label{eq:multiplication-ext-tx}
\Ext^p(\cO_\tX(h-e_1),\cO_\tX(h-e_2)) \otimes \Ext^q(\cO_\tX(h-e_2),\cO_\tX(h-e_3)) \to \Ext^{p+q}(\cO_\tX(h-e_1),\cO_\tX(h-e_3))
\end{equation}
is an isomorphism when $p = 0$ or $q = 0$.
For this consider exact sequences
\begin{equation}\label{eq:e12}
0 \to \cO_\tX(h - e_1) \xrightarrow{\ \Delta_{12}\ } \cO_\tX(h - e_2) \to \cO_{\Delta_{12}}(-1) \to 0,
\end{equation}
\begin{equation}\label{eq:e23}
0 \to \cO_\tX(h - e_2) \xrightarrow{\ \Delta_{23}\ } \cO_\tX(h - e_3) \to \cO_{\Delta_{23}}(-1) \to 0,
\end{equation}
where $\Delta_{12} = E_1 - E_2$ and $\Delta_{23} = E_2 - E_3$.
Using Lemma~\ref{lemma:pic-tx}, we compute
\begin{equation*}
\Ext^\bullet(\cO_\tX(h-e_1),\cO_{\Delta_{23}}(-1)) \cong
H^\bullet(\Delta_{23},\cO_\tX(e_1 - h)\vert_{\Delta_{23}} \otimes \cO_{\Delta_{23}}(-1)) =
H^\bullet(\Delta_{23},\cO_{\Delta_{23}}(-1)) = 0.
\end{equation*}
Applying the functor $\Ext^\bullet(\cO_\tX(h-e_1),-)$ to~\eqref{eq:e23}, we deduce that~\eqref{eq:multiplication-ext-tx} is an isomorphism for~$q = 0$. 
Similarly, by Serre duality $\Ext^\bullet(\cO_{\Delta_{12}}(-1),\cO_\tX(h-e_3))$ is dual to $\Ext^\bullet(\cO_\tX(e_1 + e_2 - 2h),\cO_{\Delta_{12}}(-1))$, and
a computation similar to the above shows it is zero.
Applying the functor $\Ext^\bullet(-,\cO_\tX(h-e_3))$ to~\eqref{eq:e12}, we deduce that~~\eqref{eq:multiplication-ext-tx} is an isomorphism for $p = 0$. 

To describe $\tcA_3$ we only need to compute 
\begin{equation*}
\Ext^p(\cO_\tX(h), \cO_\tX(2h - e_1 - e_2 - e_3)) \cong H^p(\tX, \cO_\tX(h - e_1 - e_2 - e_3)).
\end{equation*}
Using exact sequences
\begin{align*}
0 \to \cO_\tX(h - e_1) \to \cO_\tX(h) &\to \cO_{E_1} \to 0,\\
0 \to \cO_\tX(h - e_1 - e_2) \to \cO_\tX(h - e_1) &\to \cO_{E_2} \to 0,\\
0 \to \cO_\tX(h - e_1 - e_2 - e_3) \to \cO_\tX(h - e_1 - e_2) &\to \cO_{E_3} \to 0,
\end{align*}
we conclude that $H^\bullet(\tX, \cO_\tX(h - e_1 - e_2 - e_3)) = 0$ 
if the three centers of the blowups are not contained on a line (i.e., in types~0, 2, and 4), and 
$H^0(\tX, \cO_\tX(h - e_1 - e_2 - e_3)) = H^1(\tX, \cO_\tX(h - e_1 - e_2 - e_3)) = \kk$ otherwise.
By Proposition~\ref{proposition:rm-equivalence} this describes $\tcA_3$.

\label{lemma:ker-pis}
We have 
\begin{equation*}
\tcA_1^- \cap \Ker \pi_* = 0,
\qquad 
\tcA_2^- \cap \Ker \pi_* = \langle \cO_{\Delta}(-1) \rangle^\oplus_{\Delta \in \bDelta_2},
\quand
\tcA_3^- \cap \Ker \pi_* = \langle \cO_{\Delta}(-1) \rangle^\oplus_{\Delta \in \bDelta_3}.
\end{equation*}
Moreover, for any $\cF \in \Ker\pi_* \subset \bD^-(\tX)$ there is a canonical direct sum decomposition 
\begin{equation*}
\cF = \cF_2 \oplus \cF_3
\end{equation*}
with $\cF_j \in \tcA_j^- \cap \Ker \pi_*$.

\label{proposition:sod-dbx-}
The subcategories $\cA_i^- = \{ \cF \in \bD^-(X) \mid  \pi^*(\cF) \in \tcA_i^- \} \subset \bD^-(X)$ form a semiorthogonal decomposition
\begin{equation*}
\bD^-(X) = \langle \cA_1^-, \cA_2^-, \cA_3^- \rangle
\end{equation*}
with projection functors given by
\begin{equation}
\label{eq:alpha}
\alpha_i = \pi_* \circ \tilde\alpha_i \circ \pi^*.
\end{equation}
Moreover, we have
\begin{equation}\label{eq:pis-ai}
\pi_*(\tcA_i^-) = \cA_i^-.
\end{equation}

\label{proposition:sod-dbx}
The subcategories 
\begin{equation*}
\cA_i := \cA_i^- \cap \bD(X) = \{ \cF \in \bD(X) \mid \pi^*(\cF) \in \tcA_i^- \} \subset \bD(X)
\end{equation*}
provide a semiorthogonal decomposition~\eqref{eq:dbx}.
Its projection functors $\alpha_i$ are given by~\eqref{eq:alpha}; they preserve boundedness and have finite cohomological amplitude.
Finally, $\cA_i = \pi_*(\tcA_i)$.

\label{proposition:gamma}
The functor 
\begin{equation}\label{def:gamma}
\gamma := \pi_* \circ \tilde\gamma \circ \pi_m^* \colon \bD^-(\kk[t]/t^m) \to \bD^-(X).
\end{equation}
is fully faithful and preserves boundedness.
Moreover, the diagrams
\begin{equation}
\label{eq:gamma-tgamma}
\vcenter{\xymatrix@C=5em{
\bD^-(\tR_m) \ar[r]^-{\tilde\gamma} \ar[d]_{\pi_{m*}} &
\bD^-(\tX) \ar[d]^{\pi_{*}} 
\\
\bD^-(\kk[t]/t^m) \ar[r]^{\gamma} &
\bD^-(X)
}}
\qquad\text{and}\qquad
\vcenter{\xymatrix@C=5em{
\bD^-(\tR_m) \ar[r]^-{\tilde\gamma} &
\bD^-(\tX)  
\\
\bD^-(\kk[t]/t^m) \ar[r]^{\gamma} \ar[u]^{\pi_m^{*}} &
\bD^-(X) \ar[u]_{\pi^{*}}
}}
\end{equation}
are both commutative.

\label{proposition:sod-cai}
The fully faithful functors $\gamma_1,\dots,\gamma_s$ induce a completely orthogonal decomposition 
\begin{equation*}
\cA_i = \bD(\kk[t]/t^{m_1}) \times \dots \times \bD(\kk[t]/t^{m_s}).
\end{equation*}

Consider the semiorthogonal decompositions
\begin{equation*}
\bD(\tX) = \langle \tcA_3 \otimes \omega_\tX, \tcA_1, \tcA_2 \rangle
\qquand
\bD(\tX) = \langle \tcA_2 \otimes \omega_\tX, \tcA_3 \otimes \omega_\tX, \tcA_1 \rangle,
\end{equation*}
obtained from~\eqref{eq:dbtx} by mutations.
Since $\omega_\tX \cong \pi^*\omega_X$ and $\omega_X$ is a line bundle on $X$, we have 
\begin{equation*}
\pi_*(\tcA_i \otimes \omega_\tX) = \pi_*(\tcA_i) \otimes \omega_X = \cA_i \otimes \omega_X,
\end{equation*}
hence the arguments of this subsection also prove semiorthogonal decompositions


\begin{equation}\label{eq:dbx-other}
\bD(X) = \langle \cA_3 \otimes \omega_X, \cA_1, \cA_2 \rangle
\qquand
\bD(X) = \langle \cA_2 \otimes \omega_X, \cA_3 \otimes \omega_X, \cA_1 \rangle.
\end{equation}
Since the twist by $\omega_X$ is an autoequivalence of $\bD(X)$, these decompositions together with~\eqref{eq:dbx} 
show that each $\cA_i$ is admissible.
Indeed, (up to a twist) each $\cA_i$ appears in one of the three decompositions on the left, and in one on the right,
hence it is both left and right admissible.

\label{proposition:dbx-dual}
If $X$ is a sextic del Pezzo surface over an algebraically closed field, there is a semiorthogonal decomposition 
\begin{equation}
\label{eq:dbx-dual}
\bD(X) = \langle \cA_3^\vee, \cA_2^\vee, \cA_1^\vee \rangle,
\end{equation}
where
\begin{equation*}
\cA_i^\vee := \{ \cF \in \bD(X) \mid \cF^\vee \in \cA_i \} \cong \bD(Z_i),
\end{equation*}
and $\cA_i$ are the components of~\eqref{eq:dbx}.
Moreover, this semiorthogonal decomposition 
is right mutation-dual to~\eqref{eq:dbx}, i.e., $\cA_1^\vee = \cA_1$, $\cA_2^\vee = \LL_{\cA_1}(\cA_2)$ and $\cA_3^\vee = \LL_{\cA_1}(\LL_{\cA_2}(\cA_3))$.

\label{lemma:sheaves-y-z}
Let $Z = \Spec(\kk[t]/t^m)$.
For any scheme $Y$ we have an equivalence 
\begin{equation*}
\coh(Y \times Z) \cong \coh(Y,\cO_Y[t]/t^m),
\end{equation*}
where the right hand side is the category of coherent sheaves $\cF$ on $Y$ with an operator $t \colon \cF \to \cF$ such that $t^m = 0$.
An object $(\cF,t) \in \coh(Y,\cO_Y[t]/t^m)$ considered as a sheaf on $Y \times Z$ is flat over $Z$ if and only if all the maps in the next chain of epimorphisms
\begin{equation}\label{eq:t-quotients}
\xymatrix@1{\cF/(t\cF) \ar@{->>}[r]^-t & (t\cF)/(t^2\cF) \ar@{->>}[r]^-t & \ \dots\  \ar@{->>}[r]^-t & (t^{m-1}\cF)/(t^m\cF)}
\end{equation}
are isomorphisms.

\label{lemma:e-z-small}
$(1)$ 
If $z$ is the unique closed $\kk$-point of $Z_1$ then $\gamma_{Z_1}(\cO_z) \cong \cO_X \cong \pi_*\cO_\tX$.


\noindent$(2)$
Let $z \in Z_2$ be a closed $\kk$-point and let $\cE_z := \gamma_{Z_2}(\cO_z) \in \bD(X)$ be the corresponding object.
Then
\begin{itemize}
\item[(a)] 
if the component of $Z_2$ containing $z$ is reduced and corresponds to the $i$-th blowup center, then 
\begin{equation*}
\cE_z \cong \pi_*\cO_\tX(h-e_i);
\end{equation*}
\item[(b)] 
if the component of $Z_2$ containing $z$ has length $2$
then 
\begin{equation*}
\cE_z \cong \pi_*\cO_\tX(h-e_1) \cong \pi_*\cO_\tX(h - e_2);
\end{equation*}
\item[(c)] 
if the component of $Z_2$ containing $z$ has length $3$, then
\begin{equation*}
\cE_z \cong \pi_*\cO_\tX(h-e_1) \cong \pi_*\cO_\tX(h - e_2) \cong \pi_*\cO_\tX(h - e_3).
\end{equation*}
\end{itemize}
\noindent$(3)$
Let $z \in Z_3$ be a closed $\kk$-point and let $\cE_z := \gamma_{Z_3}(\cO_z) \in \bD(X)$ be the corresponding object.
Then
\begin{itemize}
\item[(a)] 
if the component of $Z_3$ containing $z$ is reduced then 
\begin{equation*}
\cE_z \cong \pi_*\cO_\tX(h)
\qquad\text{or}\qquad 
\cE_z \cong \pi_*\cO_\tX(2h - e_1 - e_2 - e_3);
\end{equation*}
\item[(b)] 
if the component of $Z_3$ containing $z$ has length $2$ then 
\begin{equation*}
\cE_z \cong \pi_*\cO_\tX(h) \cong \pi_*\cO_\tX(2h - e_1 - e_2 - e_3).
\end{equation*}
\end{itemize}
In all these cases, $\cE_z$ is a globally generated sheaf, and if $z \in Z_d$ then
\begin{equation*}
\dim H^0(X,\cE_z) = d
\qquand
H^{i}(X,\cE_z) = 0
\quad\text{for $i \ne 0$}.
\end{equation*}

\label{proposition:e-z-big}
Both $\fE_Z$ and $\tfE_Z$ are vector bundles of rank~$\ell(Z)$ on~$X$ and~$\tX$ respectively, and
\begin{equation}
\label{eq:ez-pullback}
\fE_Z \cong \pi_*(\tfE_Z).
\end{equation}
Moreover, $\fE_Z$ is an iterated extension of the sheaf $\cE_z$, where $z$ is the closed point of~$Z$.
In particular, the bundle $\fE_Z$ is globally generated with $\dim H^0(X,\fE_Z) = d\ell(Z)$ and $H^i(X,\fE_Z) = 0$ for $i \ne 0$.

\label{proposition:fm-zd}
For each $d \in \{1,2,3\}$ there is a sheaf 
\begin{equation*}
\cE_{Z_d} \in \coh(X \times Z_d),
\end{equation*}
flat over $Z_d$, such that $p_{X*}\cE_{Z_d} \cong \fE_{Z_d}$, and the equivalence $\gamma_{Z_d} \colon \bD(Z_d) \to \cA_d \subset \bD(X)$ of Corollary~\textup{\ref{corollary:dbx-z2-z3}} can be written as
\begin{equation*}
\gamma_{Z_d} \cong \Phi_{\cE_{Z_d}} \colon \bD(Z_d) \to \bD(X),
\end{equation*}
where $\Phi_{\cE_{Z_d}}$ is the Fourier--Mukai functor with kernel $\cE_{Z_d}$.
Moreover, the equivalence \mbox{$\bD(Z_d) \cong \cA_d^\vee \subset \bD(X)$} of Proposition~\textup{\ref{proposition:dbx-dual}} is given by the Fourier--Mukai functor $\Phi_{\cE_{Z_d}^\vee}$ with kernel $\cE_{Z_d}^\vee$.

\label{corollary:a-as-orthogonals}
The components $\cA_2$ and $\cA_3$ of $\bD(X)$ are compactly generated by the bundles $\fE_{Z_2}$ and~$\fE_{Z_3}$ respectively.
In particular, we have $\cA_2 = {}^\perp \cO_X \cap \fE_{Z_3}^\perp$ and $\cA_3 = {}^\perp \cO_X \cap {}^\perp\fE_{Z_2}$.

By Corollary~\ref{corollary:pis-epi} we can write $\cF = \pi_*\tcF$ for some $\tcF \in \bD(\tX)$, hence by adjunction
\begin{equation*}
\chi(\fE_{Z_d}, \cF) = \chi(\fE_{Z_d},\pi_*\tcF) = \chi(\pi^*\fE_{Z_d},\tcF) = \chi(\tfE_{Z_d},\tcF).
\end{equation*}
As it is explained in Proposition~\ref{proposition:e-z-big} the bundle $\tfE_{Z_2}$ 
is an extension (possibly trivial) of the line bundles~$\cO_\tX(h-e_i)$ for $i = 1,2,3$, hence 
\begin{equation*}
\ch(\tfE_{Z_2}) = \sum \ch(\cO_\tX(h-e_i)) = 3 + (3h - e_1 - e_2 - e_3) = 3 - K_\tX = 2\ch(\cO_\tX) + \ch(\omega_\tX^{-1}) - 3\ch(\cO_\tP),
\end{equation*}
where $\tP$ is a general point on $\tX$.
Therefore, by Riemann--Roch and adjunction we have
\begin{equation*}
\chi(\tfE_{Z_2},\tcF) = 
2\chi(\cO_\tX,\tcF) + \chi(\omega_\tX^{-1},\tcF) - 3\chi(\cO_\tP,\tcF) =
2\chi(\cO_X,\cF) + \chi(\omega_X^{-1},\cF) - 3\chi(\cO_{\pi(\tP)},\cF),
\end{equation*}
which gives the first equality.
Similarly, for $\tfE_{Z_3}$ we have
\begin{equation*}
\ch(\tfE_{Z_3}) = \ch(\cO_\tX(h)) + \ch(\cO_\tX(2h - e_1 - e_2 - e_3)) = 
\ch(\cO_\tX) + \ch(\omega_\tX^{-1}) - 2\ch(\cO_\tP),
\end{equation*}
and using Riemann--Roch and adjunction in the same way as before, we finish the proof.

Let $S$ be an arbitrary base scheme and $\cF$ a coherent sheaf on $X \times S$ flat over $S$ and such that 
for any geometric point $s \in S$ the restriction $\cF_s = i_{X \times s}^*(\cF)$ is a semistable (i.e., torsion free) sheaf with Hilbert polynomial~$h_d(t)$ for $d \in \{2,3\}$.
By Lemma~\ref{lemma:md-points} it follows that 
\begin{equation*}
\cF_s \cong \cE_z 
\end{equation*}
for a unique closed point $z \in Z_d$.

Consider the semiorthogonal decomposition
\begin{equation}\label{eq:dbx-s}
\bD(X \times S) = \langle \cA_{1S}, \cA_{2S}, \cA_{3S} \rangle = \langle \bD(S), \bD(Z_2 \times S), \bD(Z_3 \times S) \rangle,
\end{equation}
obtained by the base change $S \to \Spec(\kk)$ (\cite[Theorem~5.6]{kuznetsov2011base}) from~\eqref{eq:dbx-dz} 
(the second equality follows from \cite[Theorem~6.4]{kuznetsov2011base} and Proposition~\ref{proposition:fm-zd}).
Since by Proposition~\ref{proposition:fm-zd} the embedding functors of~\eqref{eq:dbx-dz} are the Fourier--Mukai functors given by the sheaves $\cE_{Z_d}$,
the embedding functors of~\eqref{eq:dbx-s} are given by the pullbacks $\cE_{Z_d} \boxtimes \cO_S$ of $\cE_{Z_d}$ via the maps $X \times Z_d \times S \to X \times Z_d$.

For any $\cF \in \bD(X \times S)$, a geometric point $s \in S$, and each $d' \in \{1,2,3\}$ we have by~\cite[(11)]{kuznetsov2011base} an isomorphism
\begin{equation*}
i_{Z_{d'} \times s}^*(\alpha_{d'S}(\cF)) \cong \alpha_{d'}(i_{X \times s}^*(\cF)) \in \bD(Z_{d'}),
\end{equation*}
where $\alpha_{d'} \colon \bD(X) \to \bD(Z_{d'})$ and $\alpha_{d'S} \colon \bD(X \times S) \to \bD(Z_{d'} \times S)$ are 
the projection functors of the semiorthogonal decompositions~\eqref{eq:dbx-dz} and~\eqref{eq:dbx-s} respectively.
Using this isomorphism for the sheaf~$\cF$ we started with, and taking into account Lemma~\ref{lemma:e-z-small}, we conclude that
\begin{equation*}
i_{Z_{d'} \times s}^*(\alpha_{d'S}(\cF)) \cong \alpha_{d'}(\cF_s) \cong \alpha_{d'}(\cE_z) \cong 
\begin{cases}
\cO_z, & \text{if $d' = d$},\\
0, & \text{otherwise}.
\end{cases}
\end{equation*} 
By Lemma~\ref{lemma:fiberwise}$(i)$ it follows that $\alpha_{d'S}(\cF) = 0$ when $d' \ne d$, hence 
\begin{equation*}
\cF \cong \Phi_{\cE_{Z_d} \boxtimes \cO_S}(\cF_d)
\end{equation*}
for some object $\cF_d \in \bD(Z_d \times S)$.
Moreover, the object $\cF_d$ is such that for any geometric point~$s \in S$ we have  $i_{Z_d \times s}^*(\cF_d) \cong \cO_z$ for some closed point~$z \in Z_d$.
By Lemma~\ref{lemma:fiberwise}$(iii)$ it follows that $\cF_d \cong \Gamma_{f_d*}\cL$, where $f_d \colon S \to Z_d$ is a morphism, $\Gamma_{f_d} \colon S \to Z_d \times S$ is its graph, and $\cL$ is a line bundle on $S$.
Therefore
\begin{equation*}
\cF \cong \Phi_{\cE_{Z_d} \boxtimes \cO_S}(\Gamma_{f_d*}\cL) 
\cong (\id_X \times f_d)^*\cE_{Z_d} \otimes p_S^*\cL.
\end{equation*}
This precisely means that the moduli functor $\cM_d(X)$ we are interested in is represented by the scheme~$Z_d$, 
and that $\cE_{Z_d}$ is a universal sheaf.

This proves the statement about~$\cM_2(X)$ and the first statement about~$\cM_3(X)$.
The same argument applied to the dual semiorthogonal decomposition~\eqref{eq:dbx-dual} instead of~\eqref{eq:dbx-dz} 
proves the statement about~$\cM_4(X)$ and the second statement about~$\cM_3(X)$.

\label{lemma:oc-decomposition}
$(i)$ If $C \subset X$ is a curve with Hilbert polynomial $h'_d(t)$ with $d \in \{2,3\}$ then there is a unique closed point $z \in Z_d$ and an exact sequence
\begin{equation*}
0 \to \cE_z^\vee \to \cO_X \to \cO_C \to 0.
\end{equation*}
Conversely, any nonzero morphism $\cE_z^\vee \to \cO_X$ is injective with cokernel isomorphic to $\cO_C$.

$(ii)$ Similarly, if $L \subset X$ is a line, i.e., a curve with Hilbert polynomial $h'_1(t)$ then there are unique closed points $z_2 \in Z_2$ and $z_3 \in Z_3$ and an exact sequence
\begin{equation*}
0 \to \cE_{z_2} \to \cE_{z_3} \to \cO_L \to 0.
\end{equation*}
Conversely, any nonzero morphism $\cE_{z_2} \to \cE_{z_3}$ is injective with cokernel isomorphic to $\cO_L$.

For the first part of~$(i)$, by Lemma~\ref{lemma:md-points}$(ii)$ it is enough to show 
that $I_C \otimes \omega_X^{-1}$ is stable with Hilbert polynomial~$h_{6-d}(t)$.
Stability is clear by Lemma~\ref{lemma:hd-stable}, and the Hilbert polynomial evidently equals 
\begin{equation*}
h_{\cO_X}(t+1) - h'_d(t+1) = (3(t+1)(t+2) + 1) - (d(t+1) + 1) = (3t + 6 - d)(t + 1) = h_{6-d}(t).
\end{equation*}



For the first part of~$(ii)$ first note that by Serre duality 
\begin{equation*}
\Ext^\bullet(\cO_L,\cO_X) \cong \Ext^\bullet(\cO_X,\cO_L(K_X))^\vee = H^\bullet(L,\cO_L(-1)) = 0 
\end{equation*}
since $L \cong {\mathbb{P}}^1$ and $L \cdot K_X = -1$.
Thus by Theorem~\ref{theorem:dbx} the structure sheaf $\cO_L$ is contained in the subcategory~$\langle \cA_2, \cA_3 \rangle$ of $\bD(X)$.
Next, again by Serre duality
\begin{equation*}
\Ext^i(\cO_L,\fE_{Z_2}) \cong \Ext^{2-i}(\fE_{Z_2},\cO_L(K_X))^\vee.
\end{equation*}
Since $\fE_{Z_2}$ is a vector bundle and $L$ is a curve, the right hand side is zero unless $i \in \{1, 2\}$.
On the other hand, $\fE_{Z_2}$ is globally generated by Proposition~\ref{proposition:e-z-big} and~\eqref{eq:cezd}, while $\cO_L(K_X) \cong \cO_L(-1)$ has no global sections, hence for $i = 2$ the right hand side is also zero.
On the other hand, by Lemma~\ref{lemma:chi-ez-f} we have
\begin{equation*}
\chi(\fE_{Z_2},\cO_L(K_X)) = 2\chi(X,\cO_L(K_X)) + \chi(X,\cO_L(2K_X)) - 3r(\cO_L(K_X)) = 2 \cdot h'_1(-1) + h'_1(-2) = -1,
\end{equation*}
and we conclude that $\Ext^\bullet(\cO_L, \fE_{Z_2}) = \kk[-1]$.
This means that there is a unique closed point $z_2 \in Z_2$ and a unique extension
\begin{equation*}
0 \to \cE_{z_2} \to \cF \to \cO_L \to 0
\end{equation*}
such that $\cF \in \cA_3$. 
It remains to note that $\cF$ is a sheaf of rank 1, hence there is a unique $z_3 \in Z_3$ such that $\cF \cong \cE_{z_3}$.

The converse statements are evident.

\label{proposition:fd-zd}
We have natural isomorphisms of Hilbert schemes
\begin{equation*}
F_1(X) \cong Z_2 \times Z_3,
\qquad
F_2(X) \cong {\mathbb{P}}_{Z_2}(p_{2*}\cE_{Z_2}),
\qquand 
F_3(X) \cong {\mathbb{P}}_{Z_3}(p_{3*}\cE_{Z_3}).
\end{equation*}

Assume $d \in \{2,3\}$.
Let $\cC \subset X \times S$ be a flat $S$-family of subschemes in $X$ with Hilbert polynomial~$h'_d(t)$.
Consider the decomposition of the structure sheaf $\cO_\cC \in \bD(X \times S)$ with respect to the semiorthogonal decomposition 
\begin{equation*}
\bD(X \times S) = \langle \cA_{3S}^\vee, \cA_{2S}^\vee, \cA_{1S}^\vee \rangle,
\end{equation*}
obtained from the decomposition of Proposition~\ref{proposition:dbx-dual} 
by the base change $S \to \Spec(\kk)$ via~\cite[Theorem~5.6]{kuznetsov2011base}.
The argument of Theorem~\ref{theorem:moduli} together with the result of Lemma~\ref{lemma:oc-decomposition}$(i)$ shows 
that there is a morphism $f_d \colon S \to Z_d$, a line bundle $\cF_d$ on $S$, and an exact sequence
\begin{equation*}
0 \to (\id_X \times f_d)^*(\cE_{Z_d}^\vee) \otimes p_S^*(\cF_d) \to \cO_{X \times S} \to \cO_\cC \to 0
\end{equation*}
The left arrow corresponds to a global section of the bundle $(\id_X \times f_d)^*(\cE_{Z_d}) \otimes p_S^*(\cF_d^\vee)$, i.e., to a morphism from $p_S^*\cF_d$ to $(\id_X \times f_d)^*(\cE_{Z_d})$.
We have 
\begin{equation*}
\Hom(p_S^*\cF_d,(\id_X \times f_d)^*(\cE_{Z_d})) \cong
\Hom(\cF_d,p_{S*}((\id_X \times f_d)^*(\cE_{Z_d}))) \cong
\Hom(\cF_d,f_d^*p_{d*}(\cE_{Z_d})),
\end{equation*}
where the first equality follows from adjunction and the second is the base change for the diagram
\begin{equation*}
\xymatrix@C=5em{
X \times S \ar[r]^-{\id_X \times f_d} \ar[d]_{p_S} & X \times Z_d \ar[d]^{p_d} \\
S \ar[r]^-{f_d} & Z_d
}
\end{equation*}
The flatness over $S$ of the cokernel $\cO_\cC$ of the morphism $(\id_X \times f_d)^*(\cE_{Z_d}^\vee) \otimes p_S^*(\cF_d) \to \cO_{X \times S}$ 
is equivalent to the corresponding morphism $\cF_d \to f_d^*p_{d*}\cE_{Z_d}$ being nonzero for every closed point $s \in S$.
Thus the Hilbert scheme functor $F_d(X)$ is isomorphic to the functor that associates to a scheme $S$ a morphism $f_d \colon S \to Z_d$ and a line subbundle in $f_d^*p_{d*}\cE_{Z_d}$, 
hence is represented by the projective bundle ${\mathbb{P}}_{Z_d}(p_{d*}\cE_{Z_d})$.

Now assume $d = 1$ and let $\cC \subset X \times S$ be a flat family of lines.
Decomposing $\cO_\cC$ with respect to~\eqref{eq:dbx-s} 
and using the argument of Theorem~\ref{theorem:moduli} together with the result of Lemma~\ref{lemma:oc-decomposition}$(ii)$,
we conclude that there are morphisms $f_2 \colon S \to Z_2$ and $f_3 \colon S \to Z_3$,
line bundles $\cF_2$ and $\cF_3$ on $S$, and an exact sequence
\begin{equation}\label{eq:o-lines}
0 \to (\id_X \times f_{2})^*(\cE_{Z_2}) \otimes p_S^*(\cF_2) \to (\id_X \times f_{3})^*(\cE_{Z_3}) \otimes p_S^*(\cF_3) \to \cO_\cC \to 0.
\end{equation}
Moreover, the pushforward to $S$ of this sequence gives (again by base change) an exact sequence
\begin{equation*}
0 \to f_{2}^*(p_{2*}\cE_{Z_2}) \otimes \cF_2 \to f_{3}^*(p_{3*}\cE_{Z_3}) \otimes \cF_3 \to \cO_S \to 0.
\end{equation*}
Since by Lemma~\ref{lemma:ps-ez} we know that $f_{d}^*(p_{d*}\cE_{Z_d})$ is a vector bundle of rank $d$ on $S$, the comparison of determinants gives  a relation
\begin{equation}\label{eq:f23-relation}
\cF_3^3 \otimes \cF_2^{-2} \cong f_{2}^*(\det(p_{2*}\cE_{Z_2})) \otimes f_{3}^*(\det(p_{3*}\cE_{Z_3})^{-1}).
\end{equation}
Denoting by $f_{23} \colon S \to Z_2 \times Z_3$ the map induced by $f_2$ and $f_3$, we deduce by adjunction and base change 
\begin{equation*}
\Hom(f_{2}^*(p_{2*}\cE_{Z_2}) \otimes \cF_2, f_{3}^*(p_{3*}\cE_{Z_3}) \otimes \cF_3) \cong

\Hom(\cF_2 \otimes \cF_3^\vee,f_{23}^*p_{23*}(p_{X2}^*\cE_{Z_2}^\vee \otimes p_{X3}^*\cE_{Z_3}))
\end{equation*}
and note that $f_{23}^*p_{23*}(p_{X2}^*\cE_{Z_2}^\vee \otimes p_{X3}^*\cE_{Z_3})$ is a line bundle (again by Lemma~\ref{lemma:ps-ez}).
The flatness over~$S$ of the cokernel $\cO_\cC$ of the morphism of~\eqref{eq:o-lines} is equivalent to the pointwise injectivity 
of the corresponding morphism $\cF_2 \otimes \cF_3^\vee \to f_{23}^*p_{23*}(p_{X2}^*\cE_{Z_2}^\vee \otimes p_{X3}^*\cE_{Z_3})$,
i.e., to this map being an isomorphism.
On the other hand, any line bundle on $S$ can be written as the tensor product of line bundles $\cF_2 \otimes \cF_3^\vee$ satisfying~\eqref{eq:f23-relation} in a unique way.
This shows that the Hilbert scheme functor is isomorphic to the functor that associates to a scheme $S$ a pair of morphisms $f_2 \colon S \to Z_2$ and $f_3 \colon S \to Z_3$,
hence is represented by $Z_2 \times Z_3$.

\label{remark:f4}
With the same argument one can prove that $p_{2*}(\cE_{Z_2}^\vee \otimes \omega_X^{-1})$ is a rank-4 vector bundle on~$Z_2$ 
and that~$F_4(X) \cong {\mathbb{P}}_{Z_2}(p_{2*}(\cE_{Z_2}^\vee \otimes \omega_X^{-1}))$.

\label{definition:family-dp6}
A family $f \colon \cX \to S$ is a {\sf du Val family} of sextic del Pezzo surfaces, if $f$ is a flat projective morphism such that 
for every geometric point $s \in S$ the fiber $\cX_s$ of $\cX$ over $s$ is a sextic du Val del Pezzo surface (Definition~\ref{definition:dp6}), 
i.e., a normal integral surface with at worst du Val singularities such that $-K_{\cX_s}$ is an ample Cartier divisor and $K_{\cX_s}^2 = 6$.

\label{theorem:sod-dp6}
Assume $f \colon \cX \to S$ is a du Val family of sextic del Pezzo surfaces.
Then there is an~$S$-linear semiorthogonal decomposition \textup{(}compatible with any base change\textup{)}
\begin{equation}
\label{eq:sod-dp6}
\bD(\cX) = \langle \bD(S), \bD(\cZ_2,\beta_{\cZ_2}), \bD(\cZ_3,\beta_{\cZ_3}) \rangle,
\end{equation}
where $\cZ_2 \to S$ and $\cZ_3 \to S$ are finite flat morphisms of degree $3$ and $2$ respectively, 
$\beta_{\cZ_2}$ and $\beta_{\cZ_3}$ are Brauer classes of order $2$ and $3$ respectively on them,
and the last two components are the twisted derived categories.

\label{proposition:md-zd}
For $d \in \{2,3,4\}$ the stack $\cM_d(\cX/S)$ is a $\Gm$-gerbe over its coarse module space 
\begin{equation*}
\cZ_d(\cX/S) := (\cM_d(\cX/S))_{\mathrm{coarse}}
\end{equation*}
with an obstruction given by a Brauer class $\beta_{\cZ_d(\cX/S)}$ of order
\begin{equation}
\label{eq:brauer-order}
\operatorname{ord} \beta_{\cZ_d(\cX/S)} = 
\begin{cases}
2, & \text{if $d = 2$ or $d = 4$},\\
3, & \text{if $d = 3$}.
\end{cases}
\end{equation}
Moreover, there is an isomorphism of the coarse moduli spaces $\sigma_{2,4} \colon \cZ_4(\cX/S) \xrightarrow{\ \sim\ } \cZ_2(\cX/S)$ and
an automorphism $\sigma_{3,3} \colon \cZ_3(\cX/S) \xrightarrow{\ \sim\ } \cZ_3(\cX/S)$, 
such that 
\begin{equation*}
\beta_{\cZ_4(\cX/S)} = \sigma_{2,4}^*(\beta_{\cZ_2(\cX/S)}^{-1}) = \sigma_{2,4}^*(\beta_{\cZ_2(\cX/S)})
\qquand
\beta_{\cZ_3(\cX/S)} = \sigma_{3,3}^*(\beta_{\cZ_3(\cX/S)}^{-1}).
\end{equation*}

\label{lemma:md-zd-base-change}
Let $\phi \colon S' \to S$ be a base change and denote $\cX' := \cX \times_S S'$.
We have
\begin{equation}
\label{eq:md-zd-base-change}
\cM_d(\cX'/S') \cong \cM_d(\cX/S) \times_S S'
\qquand
\cZ_d(\cX'/S') \cong \cZ_d(\cX/S) \times_S S'.
\end{equation} 
Moreover, isomorphisms~\eqref{eq:md-zd-base-change} are compatible with the universal families, i.e., 
\begin{equation}\label{eq:ced-base-change}
\beta_{\cZ'_d} = \phi_{\cZ_d}^*(\beta_{\cZ_d})
\qquand
\cE_{\cZ'_d} \cong \phi_{\cX \times_S \cZ_d}^*\cE_{\cZ_d}.
\end{equation}
where we set $\cZ'_d := \cZ_d(\cX'/S')$ and denote the morphisms induced by the base change
by $\phi_\cX \colon \cX' \to \cX$, $\phi_{\cZ_d} \colon \cZ'_d \to \cZ_d$, 
and $\phi_{\cX \times_S \cZ_d} \colon \cX' \times_{S'} \cZ'_d \to \cX \times_S \cZ_d$, respectively.

\label{corollary:S-s}
For any geometric point $s \in S$ there are isomorphisms
\begin{equation}
\label{eq:m-z-e-s}
\cM_d(\cX/S)_s \cong \cM_d(X),
\qquad
\cZ_d(\cX/S)_s \cong Z_d
\qquand
i_{Z_d}^*(\cE_{\cZ_d}) \cong \cE_{Z_d},
\end{equation}
where $X = \cX_s$ is the fiber of $\cX$ over $s$ and $i_{Z_d} \colon Z_d \cong \cZ_d(\cX/S)_s \hookrightarrow \cZ_d(\cX/S)$ 
is the natural embedding.

\label{lemma:zd-flat}
The maps $f_2 \colon \cZ_2 \to S$ and $f_3 \colon \cZ_3 \to S$ are finite flat maps of degree $3$ and $2$ respectively.
The relative dualizing complexes $\omega_{\cZ_2/S}^\bullet$ and $\omega_{\cZ_3/S}^\bullet$ are line bundles.

\label{lemma:phi-d-shriek}
The functor $\Phi_d$ is $S$-linear, preserves boundedness and perfectness, and its right adjoint functor is
\begin{equation}
\label{eq:phid-shriek}
\Phi_d^! \colon \bD(\cX) \to \bD(\cZ_d,\beta_{\cZ_d}),\qquad
\Phi_d^!(\cG) \cong p_{d*}\RCHom(\cE_{\cZ_d},p^!\cG).
\end{equation}

\label{lemma:phid-shriek-other}
We have an isomorphism of functors
\begin{equation*}
\Phi_d^!(\cG) \cong p_{d*}(\cE_{\cZ_d}^\vee \otimes p_d^*\omega_{\cZ_d/S} \otimes p^*(\cG)),
\end{equation*}
where $\cE_{\cZ_d}^\vee := \RCHom(\cE_{\cZ_d},\cO_{\cX \times_S \cZ_d})$ is a coherent sheaf flat over $\cZ_d$.
The kernel~$\cE_{\cZ_d}^\vee \otimes p_d^*\omega_{\cZ_d/S}$ of this functor is compativle with base changes, i.e.,
if $\phi \colon S' \to S$ is a base change, then
\begin{equation*}
\phi_{\cX \times_S \cZ_d}^*(\cE_{\cZ_d}^\vee \otimes p_d^*\omega_{\cZ_d/S}) \cong \cE_{\cZ'_d}^\vee \otimes p_d^{\prime*}\omega_{\cZ'_d/S'}.
\end{equation*}

For a Fourier--Mukai functor compatibilities with base changes are proved in~\cite[Lemma~2.42]{kuznetsov2006hyperplane}
(the assumption of finiteness of $\Tor$-dimension of the base change morphism is only used in the second half of that lemma).
It remains to note that both $\Phi_d$ and $\Phi_d^!$ are Fourier--Mukai functors (the first by definition~\eqref{eq:phid-definition} and the second by Lemma~\ref{lemma:phid-shriek-other}).

Take $d_1,d_2 \in \{1,2,3\}$ and consider the diagram
\begin{equation*}
\xymatrix{
& \cZ_{d_1} \times_S \cX \times_S \cZ_{d_2} 
\ar[dl]_{\pr_{1,2}} \ar[d]^{\pr_{1,3}} \ar[dr]^{\pr_{2,3}} \\
\cZ_{d_1} \times_S \cX & \cZ_{d_1} \times_S \cZ_{d_2} & \cX \times_S \cZ_{d_2} 
}
\end{equation*}
A standard computation shows that the composition of functors $\Phi_{d_2}^! \circ \Phi_{d_1}$ is a Fourier--Mukai functor given by the object
\begin{equation}
\label{eq:convolution}
\pr_{1,3*}(\pr_{2,3}^*(\cE_{\cZ_{d_2}}^\vee \otimes p_{d_2}^*\omega_{\cZ_{d_2}/S}) \otimes \pr_{1,2}^*(\cE_{\cZ_{d_1}})) \in \bD(\cZ_{d_1} \times_S \cZ_{d_2}, \beta_{\cZ_{d_1}}^{-1} \boxtimes \beta_{\cZ_{d_2}}).
\end{equation}

Let us prove that $\Phi_d$ is fully faithful for each $d \in \{1,2,3\}$.
For this it is enough to check that the object~\eqref{eq:convolution} in case $d_1 = d_2 = d$ is isomorphic 
(via the unit of adjunction morphism) to the structure sheaf of the diagonal.
Since the unit of the adjunction is induced by a morphism of kernels \cite{anno2012adjunction}, 
by Lemma~\ref{lemma:fiberwise} it is enough to check that for any geometric point $s \in S$ we have
\begin{equation}
\label{eq:isomorphism-diagonal}
i_{Z_d \times Z_d}^*(\pr_{1,3*}(\pr_{2,3}^*(\cE_{\cZ_{d}}^\vee \otimes p_{d}^*\omega_{\cZ_{d}/S}) \otimes \pr_{1,2}^*(\cE_{\cZ_{d}}))) \cong \delta_*\cO_{Z_d} \in \bD(Z_d \times Z_d)
\end{equation}
where $i_{Z_d \times Z_d} \colon Z_d \times Z_d \to \cZ_d \times_S \cZ_d$ is the natural embedding 
and $\delta \colon Z_d \to Z_d \times Z_d$ is the diagonal.
Using base change and isomorphisms of Lemma~\ref{lemma:md-zd-base-change} and Lemma~\ref{lemma:phid-shriek-other}, 
we can rewrite the left hand side of~\eqref{eq:isomorphism-diagonal} as the Fourier--Mukai kernel of the functor
\begin{equation*}
\bD(Z_d) \xrightarrow{\ \Phi_{\cE_{Z_d}}\ } \bD(X) \xrightarrow{\ \Phi_{\cE_{Z_d}}^!\ } \bD(Z_d),
\end{equation*}
where the functor $\Phi_{\cE_{Z_d}}$ is identified in Proposition~\ref{proposition:fm-zd} 
with the equivalence $\bD(Z_d) \cong \cA_d \subset \bD(X)$, and~$\Phi_{\cE_{Z_d}}^!$ is its right adjoint.
This composition is isomorphic to the identity, since the functor $\Phi_{\cE_{Z_d}}$ is fully faithful, 
hence we have~\eqref{eq:isomorphism-diagonal}.
Therefore, the functor $\Phi_d$ is fully faithful.





Next, let us prove that the subcategories $\Phi_d(\bD(\cZ_d,\beta_{\cZ_d})) \subset \bD(\cX)$ for $1 \le d \le 3$ are semiorthogonal.
For this it is enough to check that the object~\eqref{eq:convolution} in case $d_1 < d_2$ is zero.
Again, using Lemma~\ref{lemma:fiberwise} and base change isomorphisms of Lemma~\ref{lemma:md-zd-base-change} 
and Lemma~\ref{lemma:phid-shriek-other} we reduce to the case of $S = \Spec(\kk)$ with algebraically closed $\kk$.
In the latter case, the required vanishing follows from semiorthogonality of the subcategories 
$\Phi_{\cE_{Z_{d_i}}}(\bD(Z_{d_i})) = \cA_{d_i}$ in $\bD(X)$.


Finally, let us prove that the subcategories $\Phi_d(\bD(\cZ_d,\beta_{\cZ_d})) \subset \bD(\cX)$ for $1 \le d \le 3$ generate $\bD(\cX)$.
Take any $\cG \in \bD(\cX)$ and set 
\begin{equation*}
\cG_2 := \Cone(\Phi_3\Phi_3^!\cG \to \cG),
\qquad
\cG_1 := \Cone(\Phi_2\Phi_2^!\cG_2 \to \cG_2),
\qquand
\cG_0 := \Cone(\Phi_1\Phi_1^!\cG_1 \to \cG_1).
\end{equation*}
From full faithfulness and semiorthogonality it easily follows that $\Phi_1^!(\cG_0) = \Phi_2^!(\cG_0) = \Phi_3^!(\cG_0) = 0$.
Then Lemma~\ref{lemma:phid-linear} implies that for any geometric point $s \in S$ setting $\cG_{0s} = i_{X}^*(\cG_0) \in \bD(X)$ to be the restriction of $\cG_0$ to the fiber $X = \cX_s$, 
we have $\Phi_d^!(\cG_{0s}) = 0$ for all $d$.
By semiorthogonal decomposition~\eqref{eq:dbx-dz} this means that $\cG_{0s} = 0$.
Hence by Lemma~\ref{lemma:fiberwise}$(i)$ we have $\cG_0 = 0$.
Thus we have a chain of morphisms
\begin{equation*}
\cG =: \cG_3 \to \cG_2 \to \cG_1 \to \cG_0 = 0
\end{equation*}
with $\Cone(\cG_{d} \to \cG_{d-1}) \in \Phi_d(\bD(\cZ_d,\beta_{\cZ_d}))$, which proves the required semiorthogonal decomposition.

This semiorthogonal decomposition is $S$-linear since by Lemma~\ref{lemma:phi-d-shriek} its embedding functors~$\Phi_d$ are $S$-linear,

and its compatibility with base changes follows from~\cite[Theorem~6.4]{kuznetsov2011base} 
together with Lemma~\ref{lemma:phid-linear} and Lemma~\ref{lemma:md-zd-base-change}.

\label{proposition:sod-dp6-perfect-unbounded}
The components of the semiorthogonal decomposition~\eqref{eq:sod-dp6} are admissible and their projection functors have finite cohomological amplitude.
Moreover, the functors $\Phi_d$ preserve perfectness and induce a semiorthogonal decomposition
\begin{equation}
\label{eq:sod-dpx-perf}
\bD^{\mathrm{perf}}(\cX) = \langle \Phi_1(\bD^{\mathrm{perf}}(S)), \Phi_2(\bD^{\mathrm{perf}}(\cZ_2,\beta_{\cZ_2})), \Phi_3(\bD^{\mathrm{perf}}(\cZ_3,\beta_{\cZ_3})) \rangle.
\end{equation}

The functor $\Phi_d$ has finite cohomological amplitude because the sheaf $\cE_{\cZ_d}$ is flat over $\cZ_d$ by Lemma~\ref{lemma:ezd-tor-ext}
(in fact, since $p \colon \cX \times_S \cZ_d \to \cX$ is finite, the functor $\Phi_d$ is exact).
The functor $\Phi_d^!$ has finite cohomological amplitude because the sheaf $\cE_{\cZ_d}$ has finite $\Ext$-amplitude over $\cZ_d$ by Lemma~\ref{lemma:ezd-tor-ext}
(in fact, since $p_d \colon \cX \times_S \cZ_d \to \cZ_d$ is flat of relative dimension 2, the cohomological amplitude of the functor $\Phi_d^!$ equals $(0,2)$).
Thus $\Phi_d \circ \Phi_d^!$ has finite cohomological amplitude.
Since the projection functors of~\eqref{eq:sod-dp6} can be expressed as combinations of these functors

(see the proof of Theorem~\ref{theorem:sod-dp6}), 
it follows that the projection functors also have finite cohomological amplitude.



To show that the components of~\eqref{eq:sod-dp6} are admissible, note that we have two more decompositions
\begin{equation}
\label{eq:more-sod-cx}
\begin{aligned}
\bD(\cX) &= \langle \bD(\cZ_3,\beta_{\cZ_3}) \otimes \omega_{\cX/S}, \bD(S), \bD(\cZ_2, \beta_{\cZ_2}) \rangle,
\\
\bD(\cX) &= \langle \bD(\cZ_2, \beta_{\cZ_2}) \otimes \omega_{\cX/S}, \bD(\cZ_3,\beta_{\cZ_3}) \otimes \omega_{\cX/S}, \bD(S) \rangle.
\end{aligned}
\end{equation} 
Indeed, they can be established by the same argument as~\eqref{eq:sod-dp6} 
starting with the semiorthogonal decompositions~\eqref{eq:dbx-other} instead of~\eqref{eq:dbx}.
Since $\omega_{\cX/S}$ is invertible, the two above decompositions together with~\eqref{eq:sod-dp6} 
prove admissibility of all components (each of them appears on the left in one decomposition and on the right in another).

The functors $\Phi_d$ preserve perfectness by Lemma~\ref{lemma:phi-d-shriek}.

It remains to prove~\eqref{eq:sod-dpx-perf}.
For this note that the functors $\Phi_d$ have left adjoints $\Phi_d^*$ because the components of~\eqref{eq:sod-dp6} are admissible.
Since the functors $\Phi_d$ commute with arbitrary direct sums, it follows from~\cite[Theorem~5.1]{neeman1996grothendieck}
that the functors $\Phi_d^*$ preserve perfectness.
Since the projection functors of~\eqref{eq:sod-dp6} can be expressed as combinations of $\Phi_d \circ \Phi_d^*$,
they preserve perfectness, hence a restriction of~\eqref{eq:sod-dp6} gives~\eqref{eq:sod-dpx-perf}.

\label{proposition:sod-dual}
The relative duality functor gives a semiorthogonal decomposition
\begin{equation}
\label{eq:sod-dp6-dual}
\bD(\cX) = \langle \rD_{\cX/S}(\bD(\cZ_3,\beta_{\cZ_3})), \rD_{\cX/S}(\bD(\cZ_2,\beta_{\cZ_2})), \rD_{\cX/S}(\bD(S)) \rangle,
\end{equation}
whose components are equivalent to $\bD(\cZ_3,\beta_{\cZ_3})$, $\bD(\cZ_2,\beta_{\cZ_2})$, and $\bD(S)$ respectively.
Moreover, this decomposition is right mutation-dual to~\eqref{eq:sod-dp6}.

Since $\rD_{\cX/S}$ is an anti-autoequivalence, \eqref{eq:sod-dp6-dual} is a semiorthogonal decomposition.
Consider also the right mutation-dual decomposition
\begin{equation*}
\bD(\cX) = \langle \LL_1(\LL_2(\Phi_3(\bD(\cZ_3,\beta_{\cZ_3}))), \LL_1(\Phi_2(\bD(\cZ_2,\beta_{\cZ_2}))), \Phi_1(\bD(S)) \rangle,
\end{equation*}
where $\LL_1$ and $\LL_2$ are the mutation functors through the first and the second components of~\eqref{eq:dbcx-again} 
(they are well-defined because the components of the decomposition are admissible).
By base change together with Proposition~\ref{proposition:dbx-dual} and Lemma~\ref{lemma:fiberwise}, these two decompositions coincide.
In particular, the components of~\eqref{eq:sod-dp6-dual} are equivalent 
to $\bD(\cZ_3,\beta_{\cZ_3})$, $\bD(\cZ_2,\beta_{\cZ_2})$, and $\bD(S)$ respectively.

\label{proposition:smoothness}
Let $\cX \to S$ be a du Val family of sextic del Pezzo surfaces.
The total space $\cX$ of the family is regular if and only if all three schemes $S$, $\cZ_2$ and $\cZ_3$ are regular.

\label{remark:smoothness}
Note also that a du Val family of sextic del Pezzo surfaces $\cX \to S$ is smooth over $S$ 
if and only if the maps $\cZ_2 \to S$ and $\cZ_3 \to S$ are smooth (i.e.\ unramified).
Indeed, this follows from Corollary~\ref{corollary:S-s} 

and the description of the fibers~$Z_d$ of $\cZ_d \to S$ in Corollary~\ref{corollary:dbx-z2-z3}.

\label{lemma:xk-duval}
Assume the base field $\kk$ is algebraically closed.
The intersection $X_K$ defined by~\textup{\eqref{eq:xk}} is a sextic du Val del Pezzo surface if and only if 
\begin{itemize}
\item the line ${\mathbb{P}}(K)$ does not intersect the dual Segre variety ${\mathbb{P}}(W_1^\vee) \times {\mathbb{P}}(W_2^\vee) \subset {\mathbb{P}}(W_1^\vee \otimes W_2^\vee)$, and
\item the line ${\mathbb{P}}(K)$ is not contained in the discriminant cubic hypersurface $\cD_{W_1,W_2} \subset {\mathbb{P}}(W_1^\vee \otimes W_2^\vee)$.
\end{itemize}
Furthermore, $X_K$ is smooth if and only if the line ${\mathbb{P}}(K)$ is transversal to $\cD_{W_1,W_2}$.

Let $\cK \subset W_1^\vee \otimes W_2^\vee \otimes \cO_S$ be the tautological rank 2 bundle, 
let $\cK^\perp \subset W_1 \otimes W_2 \otimes \cO_S$ be its rank~7 annihilator, and let 
\begin{equation}
\label{eq:cx-p2p2}
\cX := ({\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)) \times_{{\mathbb{P}}(W_1 \otimes W_2)} {\mathbb{P}}_S(\cK^\perp)
\end{equation}
be the corresponding du Val family of sextic del Pezzo surfaces.

\label{proposition:dp-p2p2}
Let $\cX \to S$ be the du Val family of sextic del Pezzo surfaces defined by~\textup{\eqref{eq:cx-p2p2}}. 
Then 
\begin{equation*}
\cZ_2 = {\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \cD_{W_1,W_2},
\qquad 
\cZ_3 = S \sqcup S,
\end{equation*}
and the Brauer classes $\beta_{\cZ_2}$ and $\beta_{\cZ_3}$ are both trivial.

Using homological projective duality for ${\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)$, see Theorem~\ref{theorem:hpd-p2p2}, 
we obtain from~\cite[Theorem~6.27]{kuznetsov2007hpd} a semiorthogonal decomposition
\begin{equation*}
\bD(\cX) = \langle \Phi_{\cE_2}(\bD({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2)), \bD(S) \otimes \cO_\cX(1,0), \bD(S) \otimes \cO_\cX(0,1), \bD(S) \otimes \cO_\cX(1,1) \rangle,
\end{equation*}
where $\YY_2 \to \cD_{W_1,W_2}$ is the resolution of singularities defined in~\eqref{eq:def-yy2}, and
$\cE_2$ is the derived pullback of the sheaf $\EE_2$ defined by~\eqref{eq:hpd-kernel-xx3} with respect to the natural map 
\begin{equation}\label{eq:map-cx2}
\cX \times_S ({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2) \to \cX_2 \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2
\end{equation} 
(we will discuss this map below), where $\cX_2$ is the universal hyperplane section of ${\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)$.
Mutating the last component to the far left (note that $K_\cX = \cO_\cX(-1,-1)$ in the relative Picard group~$\Pic(\cX/S)$), we get
\begin{equation}
\label{eq:sod-cx-p2p2}
\bD(\cX) = \langle \bD(S) \otimes \cO_\cX, \Phi_{\cE_2}(\bD({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2)), \bD(S) \otimes \cO_\cX(1,0), \bD(S) \otimes \cO_\cX(0,1) \rangle.
\end{equation}
We claim that this decomposition agrees with the general decomposition~\eqref{eq:dbcx-again} of a du Val family of sextic del Pezzo surfaces.

Indeed, the last two components of~\eqref{eq:sod-cx-p2p2} can be considered as the derived category of~$S \sqcup S$ (the trivial double covering of $S$) embedded via the Fourier--Mukai functor with kernel
\begin{equation*}
\cE_3 := \cO_\cX(1,0) \sqcup \cO_\cX(0,1) \in \bD(\cX \sqcup \cX) = \bD(\cX \times_S (S \sqcup S)),
\end{equation*}
and the second component is the derived category of 
\begin{equation*}
{\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2 = {\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \cD_{W_1,W_2}
\end{equation*}
(recall that $\YY_2$ maps birationally onto $\cD_{W_1,W_2}$ and ${\mathbb{P}}_S(\cK)$ by definition of $S$ 
does not touch the indeterminacy locus ${\mathbb{P}}(W_1^\vee) \times {\mathbb{P}}(W_2^\vee)$ of that birational isomorphism),
which is a flat degree~3 covering of~$S$ (since $\cD_{W_1,W_2}$ is a hypersurface of degree~3), 
and it is embedded into~$\bD(\cX)$ via the Fourier--Mukai functor with kernel~$\cE_2$.

Let us check that both $\cE_2$ and $\cE_3$ are flat families of torsion-free rank 1 sheaves 
on fibers of~$\cX$ over~$S$ with Hilbert polynomials $h_2(t)$ and $h_3(t)$ respectively, parameterized by the schemes
\begin{equation*}
\cZ'_2 := {\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2
\qquand
\cZ'_3 := S \sqcup S.
\end{equation*}
For the second family flatness is clear and Hilbert polynomial computation is straightforward, so we skip it.
For the first family we note that the map~\eqref{eq:map-cx2} is flat.
Indeed, by~\eqref{eq:cx-p2p2} we have
\begin{equation*}
\cX \times_S ({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2) =
\Big(({\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)) \times_{{\mathbb{P}}(W_1 \otimes W_2)} {\mathbb{P}}_S(\cK^\perp)\Big) \times_S \Big({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2\Big),
\end{equation*}
while 
\begin{equation*}
\cX_2 \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2 = 
({\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)) \times_{{\mathbb{P}}(W_1 \otimes W_2)} Q \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2,
\end{equation*}
where $Q \subset {\mathbb{P}}(W_1 \otimes W_2) \times {\mathbb{P}}(W_1^\vee \otimes W_2^\vee)$ is the incidence quadric, so the map~\eqref{eq:map-cx2} is induced 
by the natural map ${\mathbb{P}}_S(\cK^\perp) \times_S {\mathbb{P}}_S(\cK) \to Q = \Fl(1,8;W_1^\vee \otimes W_2^\vee)$.
This map factors as 
\begin{equation*}
{\mathbb{P}}_S(\cK^\perp) \times_S {\mathbb{P}}_S(\cK) \hookrightarrow 
{\mathbb{P}}_{\Gr(2,W_1^\vee \otimes W_2^\vee)}(\cK^\perp) \times_{\Gr(2,W_1^\vee \otimes W_2^\vee)} {\mathbb{P}}_{\Gr(2,W_1^\vee \otimes W_2^\vee)}(\cK) = 
\Fl(1,2,8;W_1^\vee \otimes W_2^\vee) \to Q.
\end{equation*}
The first map is an open embedding, while the last map is a ${\mathbb{P}}^6$-bundle, so the composition is flat (and even smooth).

Recall the embedding of the Weil divisor $\YY_2 \times {\mathbb{P}}(W_2) \hookrightarrow \cX_2 \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2$ defined by~\eqref{diagram:yy-cx3}.
Its preimage under the map~\eqref{eq:map-cx2} is a Weil divisor in $\cX \times_S ({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2)$ 
such that for any geometric point~$(K,b,w_1)$ of $\cZ'_2 := {\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2$ its fiber is the Weil divisor 
\begin{equation*}
L := X_K \times_{{\mathbb{P}}(W_1)} \{w_1\} \subset X_K,
\end{equation*}
i.e., a line on the sextic del Pezzo surface $X_K$ contracted by the projection $X_K \to {\mathbb{P}}(W_1)$ to the point~$\{w_1\} \in {\mathbb{P}}(W_1)$.
Thus, by~\eqref{eq:hpd-kernel-xx3}, the sheaf we are interested in is the twisted ideal $\cI_L \otimes \cO_{{\mathbb{P}}(W_1)}(1)$.
In particular, it is torsion-free, and its Hilbert polynomial equals~$h_2(t)$.

Therefore, the families of sheaves $\cE_2$ and $\cE_3$ induce maps 
\begin{equation*}
\mu_2 \colon \cZ'_2 \to \cZ_2(\cX/S)
\qquand 
\mu_3 \colon \cZ'_3 \to \cZ_3(\cX/S)
\end{equation*}
such that the Brauer classes $\mu_2^*(\beta_{\cZ_2})$ and $\mu_3^*(\beta_{\cZ_3})$ are trivial 
and $\cE_2$ and $\cE_3$ are isomorphic (up to twists by line bundles on~$\cZ'_2$ and $\cZ'_3$) 
to the pullbacks of the universal bundles $\cE_{\cZ_2}$ and $\cE_{\cZ_3}$, respectively.
This means that for $d \in \{2,3\}$ we have isomorphisms of Fourier--Mukai functors
\begin{equation*}
\Phi_{\cE_{d}} \cong \Phi_{\cE_{\cZ_d}} \circ \mu_{d*} \circ T_d \colon \bD(\cZ'_d) \to \bD(\cX),
\end{equation*}
where $T_d$ is a line bundle twist in $\bD(\cZ'_d)$.

Since both $\Phi_{\cE_{\cZ_d}}$ and $\Phi_{\cE_d}$ are fully faithful, 
so is the composition $\mu_{d*} \circ T_d \colon \bD(\cZ'_d) \to \bD(\cZ_d)$.
Moreover, comparing semiorthogonal decompositions given by~\eqref{eq:dbcx-again} and~\eqref{eq:sod-cx-p2p2}, we conclude that $\mu_{d*} \circ T_d$ is essentially surjective, i.e., an equivalence of categories.
Since $T_d$ is also an equivalence, we conclude that $\mu_{d*}$ is an equivalence, hence $\mu_d$ is an isomorphism.
Thus $\cZ'_d \cong \cZ_d(\cX/S)$ and the Brauer classes $\beta_{\cZ_2}$ and $\beta_{\cZ_3}$  on~$\cZ_2(\cX/S)$ and~$\cZ_3(\cX/S)$ vanish.

\label{remark:extended-family}
Considering the family $\bar\cX \subset {\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2) \times \bar{S}$ of \emph{all} codimension 2 linear sections of~${\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)$ over $\bar{S} := \Gr(2,W_1^\vee \otimes W_2^\vee)$ 
and applying the semiorthogonal decomposition of Theorem~\ref{theorem:hpd-p2p2}, we obtain
\begin{equation*}
\bD(\bar\cX) = \langle \bD(\bar{S}), \bD(\bar{\cZ}_2), \bD(\bar{\cZ}_3) \rangle,
\end{equation*}
where $\bar{\cZ_2} = {\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2$ and $\bar{\cZ_3} = \bar{S} \sqcup \bar{S}$.
Note that the map $\bar{\cZ_2} \to \bar{S}$ is not flat --- its non-flat locus $\bar{S} \setminus S$ is equal 
to the locus of non-integral fibers of the family $\bar{\cX} \to \bar{S}$.

By Proposition~\ref{proposition:fd-md} there is a pair of rank 3 vector bundles $\cW_1$ and $\cW_2$ on $S$ such that
\begin{equation*}
F_3(\cX/S) = {\mathbb{P}}_S(\cW_1) \sqcup {\mathbb{P}}_S(\cW_2).
\end{equation*}
Moreover, the restrictions of the universal sheaf $\cE_{\cZ_3}$ on $\cX \times_S \cZ_3 = \cX \sqcup \cX$ to the two components are line bundles defining regular maps $\cX \to {\mathbb{P}}_S(\cW_1)$ and $\cX \to {\mathbb{P}}_S(\cW_2)$ respectively.
Thus, the induced map 
\begin{equation*}
\cX \to {\mathbb{P}}_S(\cW_1) \times_S {\mathbb{P}}_S(\cW_2)
\end{equation*}
is a closed embedding.
Zariski locally the bundles $\cW_1$ and $\cW_2$ are trivial, hence we obtain the required local presentation of $\cX$.
The Brauer class $\beta_{\cZ_2}$ vanishes Zariski locally by Proposition~\ref{proposition:dp-p2p2}
and~$\cZ_2$ is regular by Proposition~\ref{proposition:smoothness}, hence $\beta_{\cZ_2} = 0$.

Indeed, choosing a representative of each orbit, it is easy to see that 
$X_b$ is smooth, if $b \in \rO_7$; 
has one $A_1$ singularity (and is of type 1), if $b \in \rO_6$;
is a union of a smooth quadric and a quartic scroll, if~$b \in \rO_4$; 
and is a union of three quadrics, if $b \in \rO_3$.

Let $\cL \subset V_1^\vee \otimes V_2^\vee \otimes V_3^\vee \otimes \cO_S$ be the tautological line bundle, let $\cL^\perp \subset V_1 \otimes V_2 \otimes V_3 \otimes \cO_S$ be its rank 7 annihilator, and let 
\begin{equation}\label{eq:cx-p1p1p1}
\cX := ({\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}(V_3)) \times_{{\mathbb{P}}(V_1 \otimes V_2 \otimes V_3)} {\mathbb{P}}_S(\cL^\perp)
\end{equation}
be the corresponding du Val family of sextic del Pezzo surfaces.

\label{proposition:dp-p1p1p1}
Let $\cX \to S$ be the du Val family of sextic del Pezzo surfaces defined by~\textup{\eqref{eq:cx-p1p1p1}}. 
Then 
\begin{equation*}
\cZ_2 = S \sqcup S \sqcup S,
\qquad 
